def page(n,title,body):return f'<section class="zpg"><div class="zsec"><span class="zttl zh2">{title}</span></div>{body}<div class="zfoot"><span>ZombieSafeHouse · Presentazione per investitori</span><span>{n}</span><span>INDZ · documento riservato</span></div></section>'
def cap(t,b):return f'<div class="zcap"><h3>{t}</h3>{b}</div>'
def tab(rows,head):return '<table class="zt"><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def ul(L):return '<ul style="margin:4px 0 0 16px;padding:0;font-size:11.5px;line-height:1.5">'+''.join(f'<li>{x}</li>' for x in L)+'</ul>'
def big(L):return '<div class="big">'+''.join(f'<div><b>{a}</b><small>{b}</small></div>' for a,b in L)+'</div>'
